contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 amount) public payable {
        require(to != address(0));

        uint256 callerBalBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBalBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        require(amount > callerBalBefore);

        bool reverted;
        c.transfer(to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted &&
            c.totalSupply() == supplyBefore &&
            c.balanceOf(address(this)) == callerBalBefore &&
            c.balanceOf(to) == toBalBefore
        );
    }

    receive() external payable {}
}

