import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address to, uint256 amount) internal {
        vm.assume(to != address(0));
        uint256 callerBalBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { callerBalBefore = __r; } catch { return; }
        uint256 toBalBefore;
        try c.balanceOf(to) returns (uint256 __r) { toBalBefore = __r; } catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        vm.assume(amount > callerBalBefore);
        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted &&
            c.totalSupply() == supplyBefore &&
            c.balanceOf(address(this)) == callerBalBefore &&
            c.balanceOf(to) == toBalBefore);
    }

    function testFuzz_run(address to, uint256 amount) public {
